  if (IsCLMode())
    return llvm::opt::Visibility(options::CLOption);
  if (IsDXCMode())
    return llvm::opt::Visibility(options::DXCOption);
  if (IsFlangMode())
    return llvm::opt::Visibility(options::FlangOption);
  return llvm::opt::Visibility(options::ClangOption);
